"""Compose edition ten in the author's voice; all additions retain source boundaries."""
from composition import Section, assemble

weights=Section('需求、能力与决策权重，为什么不能成为新的资本',
    '05-weight-and-integrity.md','我设想的新体制，在政治层面上，每个人都是管理者',3)
weights.src(2,end='也不会有哪个节点占有支配数量性的代理。',new='''动态权重会不会被代理数量和历史优势占据？在我设想的新框架下，要从分配规则本身阻断这两种情况。首先，个体生活资源的分配是按需分配的，具体判断的权重是按相关能力分配的。能力和需求与财富有一个重要区别：它们不应当像资本所有权那样，仅凭过去已经占有的份额，就随着时间的累积，自动获得指数性的复利增长。我所要建立的机制，应当使过去的判断优势不能兑换成永久的支配权，也不能使某个节点仅凭拥有更多代理，就占有支配性的决策份额。''',reason='保留按需与按能力分工、防止复利式权力积累的主张；把绝对保证改为制度必须实现的条件，不把所有需求能力正态分布写成事实')
weights.add('''这里需要把能力差异、测量分布和制度权力分开。人的需求和能力涉及不同的维度与处境，不能预先断定每一种需求、每一种能力都服从正态分布。已有研究对一些职业的绩效发现了明显偏离正态的分布；这也不能反过来证明人的一切内在能力都是幂律分布，因为绩效还包含机会、资源和评价方式的影响。[有关绩效分布的研究](https://www.hermanaguinis.com/pdf/PPsych2012.pdf)''',reason='区分实测绩效与内在能力，避免用另一种分布替换未经证明的普遍假设')
weights.add('''即使某项能力评分近似正态，评分怎样转换为权重，仍然会改变结果。举一个只说明转换作用的例子：三个评分是1、2、3，若直接按评分归一化，最高者占一半；若先变成10、100、1000再归一化，最高者就超过九成。这三个数字不是人口分布模型，却足以说明：能力差距有限，不等于制度一定不会放大它。真正需要取消的是“优势可以无边界地继续兑换支配权”的转换机制。''',reason='用可直接核算的例子解释分布与权重映射不同，避免由正态推出不集中')
weights.add('''所以，更多代理首先代表完成任务的工具更多，不代表更多独立的人，也不自动增加其委托人的基本权利。某项公共任务可以使用很大的计算资源，但资源属于任务的安排，不属于负责人的永久个人份额。相关能力的权重需要随任务、证据和反馈修订；基本生活保障、个人资料的授权和共同规则的修改，则不能被一个专业评分包办。这样，防止支配才成为可检查的制度关系，而不依赖人群恰好具有哪一种分布。''',reason='补足从分配原则到代理计权与任务资源边界的具体逻辑')
weights.src(2,start='我们要防止的是恶意的破坏和篡改能力，',new='''我们还要防止恶意的破坏和篡改能力，就像加密货币的账本系统需要应对造假账一样。这里可以借鉴的，是把攻击者能够控制什么、诚实参与者怎样核验、出现分歧时怎样处理，都写成明确规则。''',reason='保留账本抗攻击类比，去掉不适用于全部系统的过半算力保证')
weights.add('''但是，“作恶算力不到一半”只在特定协议及其假设下具有相应含义。比特币白皮书讨论了工作量证明链中诚实算力占优时的追赶概率，并要求节点检查交易有效性；它没有证明少于半数算力就不可能盗用密钥、伪造原始观察或滥用已获权限。Merkle-DAG的内容核验、历史一致性、身份与授权、实际执行，需要分别设计。攻击比例的门槛必须从所选协议中推导，不能把一个账本模型的条件直接搬到整个人类社会。[比特币白皮书](https://bitcoin.org/bitcoin.pdf)''',reason='说明多数算力条件的适用范围及内容记录与现实行为保护的区别')

chapter=Section('文明的技术力量与自我治理能力','01-chapter.md','## 个人信息采集、数据主权与技术落地\n')
chapter.h('正向与负向连锁反应，是两种理想化方向')
chapter.src(3,new='''关于以牙还牙策略正反方向的连锁反应，需要指出的是，这两个方向首先是一种理想型的简化模型。现实生活中，可以用一些接近两端的现象帮助理解，比如合作无间的终身伴侣或挚友之间的爱情和友情，比如因为琐事引发矛盾直至爆发冲突、引发血案的刑事案件。日常生活中的大量情况是介于两者之间的，合作与背叛互相间杂，误会与修复反复出现，难以预测和控制。''',reason='去掉对会话轮次的依赖；保留两个极端的例子，不把其发生比例写成已有统计结论')
chapter.add('''一个人会在某件事上合作，又在另一件事上防守；一段长期友谊也会发生误判，一次冲突也可能因为解释和补救而停止。真正值得研究的，因此不是把所有人分成永远合作与永远背叛的两类，而是哪些条件让互动向合作移动，哪些条件让它滑向对抗，以及偏离之后能不能返回。重复博弈中不同策略在误差、收益和选择条件下会呈现不同结果，这正是需要比较机制的原因。[关于互惠策略与纠错的研究](https://www.nature.com/articles/364056a0)''',reason='把两极图景接到混合互动、误判与修复，不把TFT当作普遍行为定律')
chapter.h('从有限的个人经验，到能够积累的文明知识')
chapter.src(4,end='然后进一步在实践中检验和修正完善升级理论的过程。',new='''从人类社会的发展进程来看，早期的人类文明，人们既缺乏充分可靠的理论知识指导，又缺乏有效收集推理判断所需相关信息的手段，只能在人类社会活动的反复持续博弈中，凭人类智能体自身容量有限、难以持久精确存储信息的能力，以及相对于机器而言较慢、容易出错的推理计算能力，对较为简单或规模较小的事物收集信息，归纳抽象，形成经验并建立理论知识，然后进一步在实践中检验、修正、完善和升级理论。''')
chapter.src(4,start='后来有了语言文字，',end='并且具备了预测修改和控制的能力。',new='''在这个漫长过程中，有了语言文字，以及书写、印刷、绘画，再到后面的拍照、录音、录像，直至计算机和AI的出现，碳基生物智能体创造了一整套硅基计算与智能技术，极大地提高了从信息采集、存储和处理，到实现归纳抽象、创造新知识、新技术、新工具的能力。所以，人类研究和发现复杂系统规律，并在一定范围内控制和改造这些系统的能力也越来越强，甚至已经开始影响地球的自然环境和自身身体的生物系统。

在这些复杂系统的交互过程中，我们可以精确测量、记录，并通过计算机和AI收集更加丰富的数据，凭借计算机的强大算力和AI辅助推理抽象的能力，认识这些复杂系统的内在机制原理，提高预测和干预这些系统的能力。比如，计算机的出现，让人们对地质、海洋和天气变化有了更加系统的认识，提高了对一些现象的预测能力；计算机和AI的出现，也让人们对生物遗传、蛋白质结构和基因系统有了更深入的认识，并在特定任务和条件下具备预测、修改和干预的能力。''',reason='保留技术扩展认知能力的脉络；区分模型预测、有限干预与全面控制，蛋白质结构预测不冒充全部折叠动力学')
chapter.add('''预测和控制仍是不同的能力。能够预报天气，不等于能够任意控制天气；能够预测蛋白质结构，也不等于已经掌握整个生命系统。天气模型与AlphaFold展示了明确任务中的进展，世界气象组织也明确区分有限的人工影响天气与缺乏科学依据的大尺度天气控制。承认这些范围，才能把自然科学已经实现的进步作为真实参照。[天气预测研究](https://arxiv.org/abs/2306.06079)、[AlphaFold论文](https://pubmed.ncbi.nlm.nih.gov/34265844/)、[世界气象组织说明](https://public.wmo.int/content/wmo-statement-weather-modification)''',reason='用已核对的原始研究和机构说明限定自然系统预测与控制的范围')
chapter.h('研究人类社会时，信息的提供者也是有意愿的参与者')
chapter.src(4,start='但是所有这些复杂系统，',end='是否愿意提供这些信息的主观意愿才是。',new='''但是，对人类文明这个复杂的社会系统来说，要收集的系统信息，是我们所有人类智能体的自身信息。与许多物理测量不同，这里的信息提供者会理解研究、评价研究，并依据自己的处境决定提供什么。即使研究人体和疾病也需要认真面对人的意愿，而社会研究更直接涉及人与人之间的利益、信任和权力。对于具有主观能动性的人类来说，收集信息和处理信息的技术能力不断提高以后，是否愿意真实地提供这些信息，就可能成为决定性的瓶颈。''',reason='修正前文生物例子也涉及人的自身信息这一不连贯处；把唯一瓶颈改为可能的决定性瓶颈')
chapter.src(4,start='对于动物，我们实际上已经采用了',end='引发了人们在道德层面的争论。',new='''对于动物，人类在一些实验中已经采用了违背动物自身意愿、限制其自由，甚至伤害或终结其生命的手段，进行信息收集和理论检验，引发了人们在道德层面的争论。''',reason='保留伦理类比，将其范围限定为一些动物实验')
chapter.src(4,start='显然通过传统的金字塔架构',end='既不全面也不真实的数据。',new='''对于人类社会，如果通过传统的金字塔架构的社会治理体系，依靠权力差距和暴力机关的威慑强行收集信息，那么即使取得了大量记录，也可能得到被权力压制扭曲、被刻意隐瞒或欺骗的、既不全面也不真实的数据。对于建立长期自愿合作而言，这种办法会同时伤害信任与信息质量。''',reason='保留权力压制可能扭曲信息的机制解释，不把全部强制调查及其结果一概断言为虚假')
chapter.add('''假如一个人知道，说出设备缺陷会让自己丢掉工作，说出真正的需要会让自己受到惩罚，那么更密集的问卷和更多摄像头，也未必能得到更好的认识。人们会学习哪些回答安全，组织也可能逐渐只听见自己愿意听见的话。于是，记录的数量增加了，系统理解自身的能力却未必随之增加。要改变这一点，需要先改变真实表达之后会发生什么。''',reason='补足从权力关系到信息选择与失真的具体例子')
chapter.src(4,start='这也是为什么人类在对大自然',end='最重要因素。',new='''在我看来，这也是为什么人类在许多领域对大自然的认知、预测的知识理论和技术改造能力，明显领先于人类对自身社会系统的认知、协调和自我约束能力的重要因素之一。信息提供者是否信任信息的使用机制，是理解这种文明失配的一条关键线索。''',reason='保留文明能力失配的判断，标明作者解释而不宣称已证明是各领域最重要的单一原因')
chapter.add('''但愿意提供信息，也不会自动解决全部认识问题。数据可能遗漏重要因素，相关关系不一定是因果关系，参与者还会根据已经公布的预测改变行动。因此，保护真实表达是重要前提，随后仍需要检验理论、识别因果、比较方案并持续修正。新机制要同时改善这些条件。''',reason='补足信息到因果与预测之间的推理环节，保留人的反应性和复杂系统不确定性')
chapter.h('挥舞巨大力量的文明，也必须学会约束自己')
chapter.src(4,start='如果人类文明操纵外部世界',end='早晚会砸到自己一样。',new='''如果人类文明操纵外部世界的能力，与理解和约束自身行为的能力不匹配，任由这种失配不断扩大，就可能做出自我伤害甚至自我毁灭的行为。它就像一个力大无比、却自身脆弱的小孩子，挥舞着千斤的链子锤：力量越来越大，却不知道怎样控制方向，最终可能砸到自己。''',reason='保留链子锤类比与文明失配风险，避免把灾难写成已证明的必然结局')
chapter.src(4,start='人类一百多年来，',end='就像当年的核武器竞赛。',new='''人类一百多年来，已经遭遇了两次世界大战、美苏冷战和核危机。面对国际间的大国对抗、AI竞赛，如果各方都怕对方先掌握了AI，就会威胁甚至毁灭自己，于是拼命地想压过对方，就可能重演当年核武器竞赛中对落后的恐惧。''',reason='更正美俄冷战为美苏冷战；将所有国家都抱同一动机改为明确的条件情境')
chapter.src(4,start='要知道，当双方都越害怕发生什么，',end='比如美国对日本投放原子弹。',new='''要知道，当双方都越害怕发生什么，又越是采取会刺激对方恐惧的行动时，就可能让这件事越容易发生。就像人们越是害怕对方会伤害自己，越是会武装自己；越是发现对方在武装自己，越是害怕，从而越是武装自己。

这种相互回应驱动的负面连锁反应，即使暂时停下来，也不等于达到了对整体更好的结果。比如，双方势均力敌，达成了互相威慑的局面，就像冷战时期美苏的核武器竞争；再比如，一方在某种关键技术上遥遥领先，领先一方使用它对另一方实施毁灭性打击，比如美国对日本广岛和长崎投放原子弹。''',reason='保留安全困境的反馈链与历史例子；不把恐惧等同必然自我实现，也不把所有结局直接定义为局部最优')
chapter.src(4,start='无论哪种都只是局部最优的结果，',end='这也是人类为什么对核技术或ai技术心怀恐惧的原因。',new='''无论哪种，都不能只因为达成了暂时稳定，或一方取得了军事优势，就被视为对人类整体更优的结果。它们仍可能具有高昂的对抗成本，以及误判、局势失控乃至自我毁灭的风险。这也是人类为什么对核技术或AI技术心怀恐惧的重要原因之一。''',reason='把局部最优判断改为具体代价与风险，避免缺少收益定义时作数学断言')
chapter.h('技术的可靠性，与使用技术的文明的可靠性')
chapter.src(4,start='实际上技术本身之所以是既能提供帮助',new='''实际上，技术本身之所以是既能提供帮助也能造成伤害的双刃剑，有两个相互联系的重要因素：一个是技术本身的可靠性，另一个则是掌握和使用这些技术的人类文明体本身的可靠性。人类在许多领域对大自然的认知、预测的知识理论和技术改造能力，明显领先于对自身社会系统的认知、协调和自我约束能力，这种现状使得第二个因素成为了不能忽视的风险和严重短板，需要我们尽早尽快地解决。否则，技术越强大，错误决策与相互对抗可能造成的伤害也越大。''',reason='保留双重可靠性的中心判断，改正错字，避免将所有风险压成两个独立且可直接排序的变量')
chapter.src(5,new='''看看现在的世界吧。一方面，我们已经具备了在特定实验条件下操纵单个原子、组合出想要的结构的能力，可以在很小的芯片上集成数以亿计的晶体管，可以通过编辑部分人类细胞的基因治疗某些疾病，可以建造飞船走向太空；另一方面，我们的社会仍然充满了意识形态冲突、政治动荡和残酷的暴力战争。小到交通路怒、家庭暴力、邻里纠纷、劳资矛盾，大到美国的国会山事件、法国历史上的学生运动所呈现的社会矛盾，更不用说已经发生的俄乌战争、美伊之间的冲突，以及以色列与阿拉伯国家和巴勒斯坦之间长期的战争与冲突。

这些事件的性质、责任与历史条件并不相同，和平表达分歧也不能与暴力伤害等同。但它们共同促使我们追问：技术能力已经如此强大，人类为什么还不能更可靠地处理自身的矛盾？如果把精力和资源过度放在发展技术的能力和可靠性上，却忽视改造人类社会体制，提高人类文明自身的协调和约束能力，使两者的差距越来越大、越来越不匹配，就可能缘木求鱼、南辕北辙，在放大伤害后果的路上越走越远，直到难以挽回。''',reason='保留科技与社会冲突的对照及主要例子；限定原子操作与基因治疗，避免把不同事件混成同一种暴力或未经核实的当日战况')
chapter.add('''单原子排列已有明确实验先例，基因编辑也已经进入特定疾病的临床治疗。这些成就说明某些能力确实已经到来，而不是说明人类已经可以任意改造物质和生命。它们使“怎样共同决定如何使用力量”成为更加现实的问题。[单原子排列实验](https://research.ibm.com/publications/positioning-single-atoms-with-a-scanning-tunnelling-microscope)、[FDA关于首批镰状细胞病基因疗法的公告](https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease)''',reason='为保留的科技例子给出一手来源，不提供治疗建议或夸大适用范围')
chapter.h('让真实分享带来保护与回报，改变文明认识自身的条件')
chapter.src(6,end='成为了整个发展进程的瓶颈问题，',new='''实际上，我们已经具备或正在逐步具备收集人类社会系统许多重要信息的客观能力，而且这些能力——基础的存储容量和算力，以及日新月异的AI技术——正在快速发展；仍在探索中的脑机接口技术，也提出了新的可能。所以，如何让人类自主提供与合作有关的自身信息，正在成为整个发展进程中的一个重要瓶颈问题。''',reason='保留技术进化与自愿分享瓶颈，避免宣称已具备收集全部社会信息的客观能力')
chapter.src(6,start='我们设计的这个新机制',end='从根本上解决这个瓶颈问题。',new='''我们设计的这个新机制，就在于试图改造旧体制，消除固化的支配性权力差，增强合作，减少对抗，从机制上限制权力的滥用和伤害的发生，为人们提供的信息建立不被用来伤害自身的实际保障，提高人们分享自身信息的主观能动性。让人们从分享个体信息中得到正向回报，进而进一步激励人们扩大有益信息分享的范围和深度，并使这个正向反馈机制能够可靠、持续地运行下去。这就是我希望从根本上改善的瓶颈。''',reason='尽量保留原段，将绝对保证表述为要建立并验证的保护机制，同时保留分享范围选择')
chapter.add('''这里的回报，不必只是金钱或名望。自己的问题更容易得到解决，提出的灵感能够找到合作者，受到损害时可以得到帮助，拒绝不必要的披露也不会失去基本保障，都是人愿意继续参与的理由。正向循环也不以不断暴露更多私人细节为唯一指标：能够在更少暴露下产生同样有用的公共知识，同样是一种进步。''',reason='补足自愿分享的利益逻辑，防止把持续增加披露变为个人义务')
chapter.src(6,start='从而更好的完成对人类文明复杂系统自身的研究，',new='''从而，更好地完成对人类文明这个复杂系统自身的研究，建立更准确的理论、更有效的社会体制，让人类文明体的内部也像高级生物体的内部一样，各个组成部分通过复杂而可靠的机制相互合作，为整体提供更强的生存能力，以及与外界更强的感知和交互能力。

所有人类个体之间，在计算机和AI的帮助下，获得更充分、更可靠的信息，以能够检验的因果关系进行推理和决策，不断提高对博弈走向、过程和结果的理解与调节能力，共同构建强大的分布式动态权重智能神经网络系统，作为人类文明体的大脑，共同参与这个文明体在宇宙中的进化和发展。''',reason='保留文明智能体的整体图景，把精确控制一切博弈改为可检验且持续提高的理解与调节能力')
chapter.add('''这种生物体的类比，借鉴的是信息反馈和功能协作，不是把人变成没有选择的细胞。共同的大脑也不应成为另一个凌驾于个体之上的主人。个人仍然能够表达不同需要、质疑判断、选择参与范围；文明对自身的控制，首先意味着参与者更有能力共同约束任意伤害，而不是少数人更有能力操纵所有人。''',reason='说明整体智能与个人主权相容的条件，连接本书已有平等和退出原则')
chapter.h('关键岔路口上的选择')
chapter.src(7,new='''现在，我们正处在这样的一个关键节点和岔路口，面对两个值得认真辨认的方向：一个方向，是在负向连锁反应中不断加大对抗，增加文明自我伤害乃至自我毁灭的危险；另一个方向，则是在正向的连锁反应中提高合作与自我修正的能力，争取迈向文明进化的奇点，迈向人类文明的新形态。我希望这篇文章能让人们对此有一个清醒、明确的认识，并作出有利于共同生存与创造的选择。''',reason='保留作者希望与方向选择，将必然结局改为可受行动影响的风险与目标')
chapter.add('''这两个方向不是两个已经写好的结局。真实社会会在合作与冲突之间反复变化，而制度的意义，就在于使我们有更好的能力识别这种变化，在错误尚可修正时纠正它，在合作刚刚出现时保护它。技术进步与制度建设应当互相促进，让文明增加力量的同时，也增加理解自己、保护自己和共同选择未来的能力。''',reason='与开篇理想模型相呼应，避免重新把现实简化为不可逆的二选一宿命')

institutions=Section('统一基本规则，扩大制度探索的多样性','06-institutional-exploration.md',
    '### 从租用资源到自己构造生产能力\n',3)
institutions.src(1,end='构造更好的人类社会制度。',new='''我想强调的是，新机制在统一基本规则的前提下，要尽可能扩大公共社会规则的多样性尝试能力。一个可进化的系统，面对近乎无限多可能性的人类社会制度规则的演化路径迷宫，怎样才能高效地并行分叉，进行多样化的探索，尽量以更高的能量使用效率、更小的进化成本，找出更快、更短、更优的演化路径，构造更好的人类社会制度？''',reason='去掉对研究轮次的依赖，保留演化迷宫与效率目标，不承诺有限资源可遍历无限路径')
institutions.add('''统一的，是使不同试验能够共存、交流并承担责任的基本规则；多样的，是具体问题怎样解决。两组人可以在不侵害彼此权益的范围内尝试不同的协作办法，记录各自的条件、成本和结果，再相互借鉴。好的局部经验不必等待一个组织统一全部社会才开始传播，失败的路径也不必让后来者重新付出同样的代价。''',reason='解释统一规则与制度多样性怎样相容')
institutions.add('''近乎无限的可能性，不意味着现实中必须穷尽每一条路径。更有效的探索，是保留多样候选，尽早排除明显无效的方向，把资源放到最能增加认识的比较上，同时为尚未被多数人理解的新方向留出机会。这里的“更优”也要说明对谁更优、在哪些条件下更优，不能只缩短某一组人的时间，却把代价转移给另一组人。现实试验与虚拟试验相互反馈，才有可能逐步提高整个探索过程的效率。''',reason='补足有限资源下的搜索、比较和外部成本条件')

laboratory=Section('虚拟人类社会实验室，让制度能够先被体验和检验','07-digital-society-laboratory.md',
    '### 先写一个读者能够进入的故事\n',3)
laboratory.src(1,start='除了你提到的现实中的多样化实验机制之外，',new='''除了现实中的多样化实验机制之外，我设想的由AI驱动的数字空间中的虚拟人类社会实验室和游戏，也可以起到巨大的加速作用。这有些像人类借助生物实验室，对生物特征和基因进行有目的的实验，加快原本在自然条件下需要漫长时间才能观察和比较的变化。''',reason='保留社会实验室与生物实验类比，不把模拟速度写成已经能压缩全部亿万年自然演化的事实')
laboratory.add('''在数字空间中，可以复制同一个初始状态，让不同分支尝试不同的规则；也可以把一次失败之前的状态保存下来，改变一个条件，再观察结果怎样变化。面对资源突然短缺、信息发生误判、参与者能力差异很大等情境，规则是否仍然能够维持合作，就不必只靠一幅理想化的宣传画来说明。''',reason='补足虚拟实验能够提供的具体操作与辨别问题')
laboratory.add('''这里需要区分三件事：故事让人理解一种生活的可能，游戏让参与者体验选择与反馈，社会模拟则试图对明确的问题给出可检验的预测。故事可以采用远未来的设定；研究模型必须说明哪些条件来自现实，哪些只是设定。已有研究用千余人的访谈或问卷构建生成式代理，在一定范围内预测回答和行为；这种进展支持继续研究，却没有把整个社会的长期演化变成已经验证的模拟能力。[生成式个体模拟研究](https://arxiv.org/abs/2411.10109v3)''',reason='区分文化叙事、真人体验和经验预测，引用研究的具体范围而不推断全球社会已可模拟')
laboratory.add('''如果所有虚拟参与者都由相似模型生成，他们可能共同遗漏现实中的某一种处境。模拟里的一百万人同时同意，也不等于现实中的一百万人真的愿意。实验应与获得同意的真实观察和小规模实践对照，检查不同人群、不同初始条件下的表现，并保留预测失败的情况。关于用大模型模拟社会参与者的方法研究，也强调人类基线、适用范围和校准的重要性。[社会模拟的方法讨论](https://arxiv.org/abs/2509.26080v2)''',reason='补足模拟到现实的验证环节，防止把生成多数当作真实同意')
laboratory.add('''因此，我所期待的加速，是让虚拟世界帮助提出方案、暴露问题、筛选值得进一步试验的方向，再由现实实践检验和修正模型。数字状态可以回退，现实中的人的损失却不能总是回退；进入真实事务时，需要重新确认授权、成本和停止条件。只有这条往返通路建立起来，游戏才可能成为制度演化的实验室，而不仅仅是把我们希望相信的未来反复演给自己看。''',reason='连接数字分叉、现实检验和个人保护，保留探索愿景')

if __name__=='__main__': assemble([weights,chapter,institutions,laboratory])
